{
  "questions": [
    {
      "question_id": "q1",
      "question": "What does the liquid look like at the measurement point?"
    },
    {
      "question_id": "q2",
      "question": "Which industry or application area is this process for?"
    },
    {
      "question_id": "q3",
      "question": "Is there a reference method that provides comparison values?"
    },
    {
      "question_id": "q4",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or a detection limit?"
    },
    {
      "question_id": "q5",
      "question": "Over what range would the target variable need to be monitored once defined?"
    },
    {
      "question_id": "q6",
      "question": "How quickly must a result be available?"
    }
  ],
  "plan": {
    "objective": "Test whether spectroscopy can distinguish representative good and off-specification samples in relation to a defined quality variable.",
    "samples_and_states": [
      {
        "text": "Collect representative retained good and off-specification samples spanning relevant process states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Obtain matched reference measurements once the quality variable and a suitable reference method have been defined.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Record MIR, NIR and Raman spectra on the same retained sample set using screening arrangements rather than a final in-line configuration.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare the methods for differences between good and off-specification samples that relate to the reference measurements.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Test any screening-derived relationship on independent material excluded from method selection and calibration.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Treat an unresolved target definition or failure to meet pre-agreed acceptance criteria as no-go for configuration selection.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "The suitability of an exact in-line sensor configuration remains un demonstrated.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify the measurement task and agree acceptance criteria.",
      "Collect representative retained good and off-specification samples.",
      "Obtain matched independent reference measurements.",
      "Record and compare MIR, NIR and Raman spectra.",
      "Validate candidate relationships on independent material.",
      "Decide go or no-go against the agreed criteria."
    ]
  },
  "decision_basis": [
    {
      "text": "Decide whether to advance by comparing results on independent material against client-agreed criteria established before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
